mapper.select:
SELECT id, name, subtitle, category_id, price, original_price, stock, sales, main_image, images, description, origin, harvest_date, shelf_life, storage, status, sort, create_time, update_time, deleted, MATCH(name, subtitle) AGAINST (#{keyword} IN NATURAL LANGUAGE MODE) AS ft_score FROM product WHERE deleted = 0 AND status = 1
AND category_id = #{categoryId}
AND MATCH(name, subtitle) AGAINST (#{keyword} IN NATURAL LANGUAGE MODE)
ORDER BY sales DESC ORDER BY create_time DESC ORDER BY price ASC ORDER BY price DESC ORDER BY ft_score DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM product WHERE deleted = 0 AND status = 1
AND category_id = #{categoryId}
AND MATCH(name, subtitle) AGAINST (#{keyword} IN NATURAL LANGUAGE MODE)
